from pathlib import Path
import html
p=Path(__file__).resolve().parents[1];out=p/'05_后台与研发说明'
def P(x):return '<p>'+x+'</p>'
def H(x):return '<h2>'+x+'</h2>'
def T(head,rows,widths):return '<table>'+''.join(f'<col style="width:{v}%">' for v in widths)+'<thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def S(n,title,body):return f'<section class="page"><div class="over">东方智慧 后端总体设计　/　{n:02d}</div><h1>{title}</h1>{body}</section>'
ss=[]
ss.append(S(1,'后端总体设计与架构方案',P('本文供项目负责人和研发团队确定后端建设方向，回答后端负责什么、为什么这样拆分、数据如何组织、业务如何流转，以及怎样从本机版本推进到可运营的线上系统。<strong>本文是架构设计方案，不是联调或测试报告。</strong>')+H('一条贯穿产品的业务主线')+P('用户从生命、身体、心智三个入口表达当下需要，进入可信内容和可执行练习，留下自己的记录，再获得适合的学习或老师服务。后端要保存这条关系链：<strong>用户需要 → 内容与实践 → 个人记录 → 回望与下一步。</strong>')+P('三大地图是同一用户体系下的三种业务视角，不拆成三个独立后端。课程、老师和AI可以服务多个地图，个人记录则始终属于具体用户。东方智慧的后端也不是医疗诊断引擎或命运结论引擎。')+H('总体选择')+P('<strong>采用模块化单体作为下一阶段主架构。</strong>沿用现有Python服务基础，先在一个部署单元内建立清晰的身份、内容、成长记录、社群、服务和集成边界。当前规模没有拆成微服务的必要；先保证业务归属、事务、权限和可维护性，后续按真实压力拆分。')+T(['设计原则','具体落点'],[('用户为中心','账号作为业务主键；三个地图、学习与服务关联到同一用户，不在前端拼出互不相通的档案'),('内容可信','来源、授权、审核和发布范围分开管理；能否公开不等于能否给AI引用'),('状态可信','未接入显示未接入；本机保存不冒充服务器保存；套餐展示不等于会员已生效'),('运营可用','后台通过API操作业务，不直接改数据库；发布、审核、版本和导出可追溯'),('演进可控','先补数据归属和业务分层，再接真实外部服务，最后完成生产部署')],[23,77])+H('现状与目标的阅读方式')+P('“现状”描述当前真实文件和能力；“目标设计”描述后续应建设的结构。现有后台界面不是整个后端，管理端只是后端的一种使用入口。本方案不把尚未实现的分层、支付、云同步或上线能力写成既成事实。')))
architecture='''<div class="row"><div>APP与网页用户端<br><small>学习 练习 个人记录 交流</small></div><div>运营管理端<br><small>内容 审核 服务 权限</small></div><div>外部服务入口<br><small>设备回调 支付回调</small></div></div><div class="arrow">身份认证 限流 参数校验 ↓</div><div class="box">API 接入层<br><small>路由 请求与响应模型 授权上下文 错误处理</small></div><div class="arrow">调用业务用例 ↓</div><div class="row"><div>身份与权限</div><div>内容与学习</div><div>成长与记录</div><div>社群与服务</div></div><div class="row"><div>计时账本</div><div>会员与权益</div><div>AI与设备适配</div><div>运营与审计</div></div><div class="arrow">统一事务与持久化接口 ↓</div><div class="row"><div>关系型业务数据库</div><div>媒体对象存储</div><div>任务与可观测性</div></div>'''
ss.append(S(2,'总体架构与分层方式',P('以下是<strong>目标逻辑分层</strong>，各层可以先存在于同一个Python应用内，不意味着立即部署多个服务。对象存储、任务基础设施及完整会员权益属于后续建设。')+architecture+H('一次业务请求如何经过后端')+P('以提交老师需求为例：路由识别请求 → 认证获得当前用户 → 校验老师是否已发布、日期和正文 → 服务模块创建待处理需求 → 在同一事务中写业务数据与必要审计 → 提交事务 → 返回需求编号与状态。用户不能自行传owner决定归属，运营也不通过直接改表处理需求。')+H('现有代码怎样演进')+T(['现状','下一步分层','目的'],[('server.py集中路由和业务逻辑','接入层只负责协议，业务规则进入相应服务模块','避免新增业务不断堆进同一处理函数'),('Store与SQL在同一文件中','持久化接口封装查询、事务与约束','业务服务不拼接分散的SQL'),('配置直接由表单进入接口','请求模型、业务模型、公开响应分离','防止私有字段随着内容对象下发前端'),('外部调用放在服务端适配','每个供应商通过统一适配边界调用','更换供应商不改业务和前端契约')],[31,40,29])+P('实施时先迁移一个模块并保持原接口兼容，再逐步拆分；不为“架构好看”重写全部业务，也不在本轮另起项目副本。')))
ss.append(S(3,'业务模块与职责划分',T(['模块','负责什么','不负责什么'],[('身份与权限','注册 登录 会话 角色 账号数据归属','不直接决定某门课程是否有付费访问权'),('内容与学习','每日一句 卡池 课程 音景 练习目录 来源 授权 发布版本','不保存用户私信或冒充设备测量'),('成长记录','生命 身体 心智观察 学习练习记录 个人档案视图','不作医疗诊断；不由运营随意改写原始自述'),('计时账本','活动会话 心跳 跨天结算 多窗口去重','不把离线空白计为使用时长；不等同支付账单'),('社群与交流','作者发布 审核 好友关系 私信','公开审核权限不等于私信阅读权限'),('老师服务','老师资料 服务需求 受理 结束 排班预约的后续扩展','未接老师排班时不承诺真实可约时段'),('会员与权益','套餐内容；目标为订阅状态 权益校验 订单与支付状态','不信任前端传来的价格或支付成功状态'),('AI与设备集成','供应商配置 请求适配 授权 数据接收 失败状态','不把生成式内容标为检测事实'),('运营与审计','管理端工作流 内容版本 审核记录 导出操作 运行支持','不绕过业务服务直接修改业务表')],[19,48,33])+H('模块之间怎样协作')+P('课程模块提供内容及访问要求，权益模块回答用户是否能读；老师服务模块引用已发布老师资料，身份模块提供当前学员；成长记录模块引用内容编号记录实际行为；AI只能通过受控的上下文接口获取用户明确允许的资料，不能任意查询整库。')+H('为什么不按页面建后端')+P('“首页”“智慧馆”“我的”是展示组合，不是独立业务主体。同一课程可出现在智慧馆、心智地图和收藏中，后端仍只有一个课程身份与发布状态；同一条个人记录可供个人档案和趋势回看引用，但不能复制成多份相互矛盾的数据。')))
ss.append(S(4,'数据库与数据关系设计',P('数据库首先保存业务事实，再提供适合页面展示的查询结果。当前SQLite已有15张表；后续不靠不断增加大JSON字段覆盖所有业务，而是逐步建立稳定主键、关系、约束和迁移版本。')+T(['数据域','当前表','关系与设计要点'],[('身份','users sessions','users.id是账号主体；会话关联账号；密码只存散列，会话令牌只存摘要'),('内容','contents revisions','kind加id唯一标识配置；版本记录内容、发布状态与排序快照'),('记录与计时','records timer_runs','records按owner kind day区分同日记录；timer_runs关联owner并约束单一活动段'),('社群','posts media','发布内容关联作者，媒体有独立所有者和访问规则'),('好友与私信','friendships messages','好友关系决定双方通信权限；消息分别保存发送人与接收人'),('老师服务','service_requests','关联学员与老师编号，保存需求、期望日期和处理状态'),('设备','devices measurements','授权连接属于账号；测量数据属于连接；指标和时间用于去重'),('配置与追溯','settings audits','配置存于服务端；审计记录操作者、动作、对象和时间')],[20,25,55])+H('需要补齐的数据结构')+P('<strong>内容授权：</strong>目标增加内容来源、授权主体、可公开范围、使用期限、是否允许收费与AI引用。三大地图标签与内容传统/授权范围是两个维度，不能因为都叫“东方文化”就混用权限。')+P('<strong>学习与成长：</strong>目标把练习会话、学习进度和收藏等浏览器记录纳入账号级模型；保留内容版本或必要快照，保证内容更新后历史行为仍能解释。')+P('<strong>订单与权益：</strong>目标增加订单、支付事件、订阅或权益授予记录。套餐内容只定义价格和说明；用户是否拥有权益由真实业务记录决定。')+H('数据库变更规则')+P('当前初始化建表不等于正式迁移机制。目标建立迁移编号、升级脚本、备份与回滚说明，新增索引对应明确查询场景。跨多张表的业务写入使用事务，不能出现业务成功但关键状态只保存一半。')))
ss.append(S(5,'个人数据与成长档案设计',H('账号归属是第一条边界')+P('当前服务器记录按账号或访客Cookie归属，浏览器仍有本地档案、收藏和偏好。目标是将“账号级业务数据”“设备级偏好”“临时离线草稿”分开：换账号不串档，换设备不丢服务器已有数据，离线草稿不能自动归给错误账号。')+H('目标写入流程')+P('用户操作 → 生成客户端操作编号 → 本地显示待同步状态 → 服务端认证并校验 → 按幂等规则落库 → 返回服务端编号、版本与更新时间 → 客户端确认已同步。离线时进入待发送队列；重连或重新登录后只重传当前账号的操作。该队列与完整读回接口尚待建设。')+H('不同记录采用不同冲突策略')+T(['数据类型','目标策略','原因'],[('签到与每日抽卡','同账号同日期幂等，保留首次服务端成功结果','防止重试生成两次签到或改变当日抽卡'),('身体与情绪自述','明确当前版本，冲突时保留双方信息或提示选择','不能静默覆盖另一个设备上的更新'),('练习及音乐会话','按会话或操作编号追加，服务端去重','多个真实练习不应被同日唯一键合并'),('收藏','按用户和内容编号唯一，增删操作可重放','多次点击和离线重试应得到一致集合'),('外观与音量','默认设备偏好，可选账号偏好同步','设备体验设置与个人业务事实分开')],[23,43,34])+H('档案如何产生')+P('成长档案由真实记录聚合生成，视图可按生命、身体、心智和日期筛选。聚合值要能追溯原始来源，不用演示分数代替真实结论。自述、练习时长、设备测量和AI辅助总结分别标注来源，不合并成未经验证的健康诊断。')+H('访客转登录')+P('目标由用户明确选择是否将该设备的访客记录归入当前账号，校验冲突并记录迁移结果；不静默把共享设备上所有历史记录并入新登录人。上线多账号和跨设备使用前，应先完成这一部分。')))
ss.append(S(6,'核心业务流程与状态设计',T(['业务','状态与流程','服务端必须把守的规则'],[('内容配置','草稿 → 发布 → 归档；修改生成版本，可恢复','发布与排序只有服务端能确定；归档不从内置默认内容复活'),('社群内容','草稿 → 待审核 → 公开或驳回；公开后可下架','作者不能直接审批自己；修改公开正文需重新审核；驳回/下架留原因'),('老师需求','待处理 → 已受理 → 已结束；符合条件时取消','学员只看自己；老师资料须公开；后续需严格限定状态迁移和排班冲突'),('设备授权','未连接 → 已同意待接入 → 收到真实数据；可解除','测量必须关联有效授权；撤权后拒绝推送；按连接 指标 时间去重'),('会员业务','当前为配置和本地流程预览；目标为待支付 → 支付确认 → 权益生效 → 到期或退款','回调验签与订单幂等；客户端成功页不能授予权益')],[19,43,38])+H('全局计时单独建账')+P('进入APP自动心跳，不提供用户暂停累计；按账号约束一个活动段，多窗口不重复计算。超过心跳有效区间后结算旧段，重新进入再开新段；跨天按时区拆分。练习播放器的暂停和全局APP使用时长是两套语义，不能共用一份“正在运行”开关。')+H('状态不只写在界面上')+P('上表是目标工作流规则。现有实现已使用这些状态值，但部分取消和受理接口仍需进一步收紧允许的前置状态。应由业务服务统一判断，例如已结束需求不能再次受理；不能仅靠隐藏按钮防止非法迁移。')+H('事务与副作用')+P('业务状态及关键审计在同一事务内提交。发送通知、长时AI任务、转码等外部副作用不要长时间占住数据库事务；出现实际异步需求时再引入任务队列与可靠事件记录。支付回调需可安全重放，设备推送需可去重。')))
ss.append(S(7,'接口权限与外部服务设计',H('接口分为三条通道')+T(['通道','身份与权限','主要边界'],[('用户业务API','登录会话或明确访客上下文','只访问本人记录、双方好友业务和已公开内容'),('运营管理API','管理角色及对象级授权','内容发布、审核、服务处理、角色与凭据配置分开授权'),('供应商回调API','供应商凭据或签名','不把用户Cookie当作设备或支付服务身份')],[24,35,41])+H('统一接入层')+P('目标统一请求校验、错误代码、请求编号、时间格式、分页和幂等约定。当前接口已使用JSON和明确HTTP状态，但错误仍主要依赖中文error文本，部分时间字段命名也不统一。演进时先兼容旧响应，再给前端明确迁移期，不一次性破坏已有客户端。')+H('AI如何接入')+P('用户问题先经过身份与上下文授权，再传给AI适配层。系统提示词、内容授权范围、模型和凭据由服务端管理；只有允许被AI引用的资料才进入检索上下文。后续应保留来源依据、失败状态与必要审计，处理超时、限额和取消。AI是学习和觉察助伴，不替代老师或医疗判断。')+H('设备如何接入')+P('用户同意 → 创建账号专属连接 → 供应商完成真实授权 → 服务端接收带时区和来源的测量 → 指标映射与校验 → 持久化 → 按本人权限返回。每个供应商独立适配；缺少SDK或OAuth资料时，不能把本地接收接口当成硬件已接通。')+H('媒体与权益')+P('当前媒体位于SQLite并按公开状态、作者和管理权限读取。生产目标为对象存储中的不可猜测对象引用，由业务API校验后提供短期授权访问；课程付费权益必须由服务端决定，不能在前端藏一个按钮就算保护完成。')+H('隐私访问')+P('管理统计、审核公开内容和读取个人自述是不同权限。常规运营优先使用元数据和统计；私信和个人自述不出现在普通管理导出中。未来如需客服访问敏感内容，应有明确目的、授权范围、期限和审计。')))
production='''<div class="box">浏览器或APP<br><small>HTTPS 与正式域名</small></div><div class="arrow">↓</div><div class="box">反向代理与入口防护<br><small>TLS 请求大小限制 访问日志</small></div><div class="arrow">↓</div><div class="box">模块化单体应用<br><small>用户API 管理API 回调API</small></div><div class="arrow">↓</div><div class="row"><div>业务关系型数据库<br><small>事务 索引 迁移</small></div><div>媒体对象存储<br><small>授权读取 生命周期</small></div><div>备份与监控<br><small>恢复 告警 追踪</small></div></div>'''
ss.append(S(8,'技术路线与部署架构',H('保留什么 改造什么')+P('现有Python业务逻辑和接口契约可以继续利用，数据库及文件仍保留在当前项目内。本机Python标准库HTTP服务和SQLite适合当前验证与小范围使用；不能直接把绑定地址改成公网就视为生产部署完成。')+production+H('数据库和媒体如何选择')+P('先以真实数据量、并发写入和备份恢复目标决定数据库演进。SQLite继续承担本机开发与验证；当需要多实例应用、更多并发写入或更成熟的运维能力时，再迁移到服务型关系数据库。迁移前建立数据库访问边界，避免业务逻辑依赖到处散落的SQLite细节。')+P('媒体体量会比文字记录增长更快，生产阶段优先把大媒体从业务库拆到对象存储，数据库保留素材编号、所有者、类型、大小、引用和审核状态。不要一开始就为尚不存在的流量引入一整套分布式系统。')+H('上线必须具备的运行能力')+P('独立环境配置与服务端密钥管理；HTTPS与生产Cookie；首次管理员安全初始化；数据库迁移；错误和访问日志；备份及恢复演练；媒体与接口限额；健康检查与告警。增加请求编号后，前台错误能够关联到服务端日志，但日志不记录密码、令牌或敏感正文。')+H('什么时候才拆服务')+P('只有出现独立伸缩、故障隔离或团队边界需求时，才考虑拆媒体处理、通知、AI长任务等模块。核心身份、内容权限与权益保持统一契约；不是因为页面多或功能多，就直接拆成大量微服务。')))
ss.append(S(9,'实施顺序与交付规划',P('按业务风险与依赖排序推进，不先花时间替换框架名称。每阶段交付可用的业务切片，并明确当前完成和后续设计的边界。')+T(['阶段','具体实施','退出条件'],[('第一阶段 数据归属','账号级本地隔离；访客迁移；个人记录读回；待同步队列；操作幂等与冲突策略','换账号不串档；重连不重复写入；跨设备恢复范围清楚'),('第二阶段 后端分层','按业务域迁出路由逻辑；封装持久化与事务；建立迁移版本；统一错误和时间约定','原接口兼容；模块职责清晰；升级与恢复可重现'),('第三阶段 可信内容与服务','来源与授权；老师服务状态校验；内容分页检索；素材所有权和访问边界','运营能管理真实内容；授权和发布范围不混淆；服务流程不靠手工改表'),('第四阶段 外部集成','真实AI与设备；正式支付和权益；超时 重试 回调去重；外部授权撤销','真实资料逐项验收；服务端判定权限和成功状态'),('第五阶段 生产交付','正式部署 配置 日志 监控 备份 恢复 规模验证','正式环境可运维；事故能追踪；不把本机结果等同公网能力')],[24,43,33])+H('当前已有基础')+P('用户与角色、内容配置、社群发布审核、好友消息、老师需求、五类观察记录、计时账本、设备接收、AI适配、版本审计和本机管理台已经具备基础。后续应围绕上述真实基础渐进改造，而不是再做一套只展示菜单的后台。')+H('需要负责人确定与提供')+P('先确定多账号与跨设备档案的目标范围、哪些内容可被AI引用、老师服务如何受理、付费会员具体权益和退款规则；再提供内容授权、真实老师资料、供应商SDK、AI权限、支付主体及部署环境。技术模块必须服从这些业务边界，不能替业务方臆造。')+H('本方案的交付边界')+P('本文件给出后端设计思路、逻辑分层、模块责任、数据与状态规则、部署路线和实施顺序。它不表示上述目标模块已全部重构完成，也不以回归通过数量替代架构说明。研发应以业务切片落实每个阶段，再分别验收。')))
css='''*{box-sizing:border-box}body{margin:0;background:#e9ece9;color:#202b24;font:15px/1.75 'Microsoft YaHei',sans-serif}.page{max-width:1000px;margin:25px auto;padding:40px 48px;background:#fff}.over{font-size:10px;letter-spacing:2px;color:#637567;margin-bottom:16px}h1{font-size:28px;color:#000;line-height:1.4;margin:0 0 23px}h2{font-size:18px;color:#000;margin:23px 0 10px;break-after:avoid}p{margin:0 0 13px;orphans:2;widows:2}table{width:100%;table-layout:fixed;border-collapse:collapse;font-size:12px;line-height:1.65;margin:12px 0 17px}th,td{padding:9px;border:1px solid #d3ddd5;vertical-align:middle;text-align:left;overflow-wrap:anywhere}th{background:#304b3a;color:white;font-weight:500}thead{display:table-header-group}tbody tr:nth-child(even){background:#f4f7f3}tr{break-inside:avoid}.row{display:flex;gap:9px;margin:9px 0}.row>div,.box{flex:1;background:#f3f6f1;border:1px solid #c9d5c9;padding:13px 10px;text-align:center}.row small,.box small{font-size:11px;color:#5f725f}.arrow{text-align:center;font-size:11px;color:#657665;margin:6px 0}.bar{max-width:1000px;margin:20px auto;text-align:right}.bar button{border:0;background:#304b3a;color:white;padding:10px 18px;border-radius:5px;cursor:pointer}@page{size:A4;margin:15mm 14mm 17mm}@media print{body{background:#fff;font-size:14.3px;line-height:1.65}.page{max-width:none;margin:0;padding:0;break-after:page}.page:last-child{break-after:auto}.bar{display:none}.over{font-size:9px;margin-bottom:11px}h1{font-size:25px;margin-bottom:18px}h2{font-size:17px;margin:18px 0 8px}p{margin-bottom:10px}table{font-size:11.4px;line-height:1.6;margin:10px 0 13px}th,td{padding:8px}.row>div,.box{padding:11px 9px}.row small,.box small{font-size:10px}.arrow{font-size:10px}}@media(max-width:650px){.page{margin:12px 0;padding:25px 18px}h1{font-size:23px}.row{flex-wrap:wrap}.row>div{min-width:120px}table{font-size:10px}th,td{padding:6px}}'''
report='<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>后端总体设计与架构方案</title><style>'+css+'</style><div class="bar"><button onclick="window.print()">打印方案</button></div>'+''.join(ss)+'</html>'
(out/'后端总体设计与架构方案.html').write_text(report,encoding='utf-8');print('Standalone backend architecture design created: 9 sections; no test-result chapter.')
